"""Family-held-out synthetic data; no Discord data is read or collected."""
import random
from dataclasses import asdict

from router import RoutingInput

# Independent human-readable scenario labels, not generated by RuleRouter.
# Every scenario family is assigned to exactly one split.
FAMILIES = {
    "RULE": [
        ("report_total", {"command": "report", "minutes": 30}, "Logging {n} minutes of Korean study today"),
        ("goal_creation", {"command": "setgoal"}, "Set a daily vocabulary goal for lesson {n}"),
        ("daily_review", {"command": "summary"}, "Show progress on synthetic day {n}"),
        ("quiz_reply", {"command": "answer"}, "Submit vocabulary response for exercise {n}"),
        ("schedule_control", {"command": "checkins"}, "Pause my scheduled reminder number {n}"),
        ("recovery_approval", {"command": "adjust"}, "Approve proposed daily adjustment {n}"),
    ],
    "CLARIFY": [
        ("missing_minutes", {"command": "report"}, "I finished a study block for exercise {n}"),
        ("negative_minutes", {"command": "report", "minutes": -1}, "My timer recorded negative minutes at exercise {n}"),
        ("excess_minutes", {"command": "report", "minutes": 2000}, "The total exceeds a day for exercise {n}"),
        ("unknown_command", {"command": "invented"}, "Try my unsupported operation number {n}"),
        ("terse_done", {}, "done{n}"),
        ("terse_help", {}, "help{n}"),
    ],
    "LLM": [
        ("work_conflict", {}, "My work shift changed and I need help planning Korean lesson {n}"),
        ("fatigue", {}, "I feel tired after work and want advice for study session {n}"),
        ("learning_strategy", {}, "How can I remember the vocabulary in chapter {n} more effectively"),
        ("motivation", {}, "I am losing interest in exercise {n} and would like to talk it through"),
        ("competing_tasks", {}, "Help me balance coursework and vocabulary project {n} this week"),
        ("reflection", {}, "Can you help interpret my difficulty with Korean practice set {n}"),
    ],
    "DEFER": [
        ("weekly_reflection", {"non_urgent": True}, "Review my weekly learning pattern for week {n} whenever convenient"),
        ("later_planning", {"non_urgent": True}, "Help plan next month after project {n} when there is time"),
        ("archive_review", {"non_urgent": True}, "Look over old practice notes from chapter {n} later"),
        ("long_term", {"non_urgent": True}, "Consider a long term vocabulary strategy for topic {n} another day"),
        ("optional_material", {"non_urgent": True}, "Suggest optional practice materials for lesson {n} sometime later"),
        ("future_schedule", {"non_urgent": True}, "Think about next semester timetable option {n} at a convenient time"),
    ],
}


def generate(seed=42, samples_per_family=20):
    if type(samples_per_family) is not int or samples_per_family < 1:
        raise ValueError("samples_per_family must be positive")
    rng = random.Random(seed)
    splits = {"train": [], "validation": [], "test": []}
    for label, families in FAMILIES.items():
        families = families.copy()
        rng.shuffle(families)
        for index, (family, metadata, template) in enumerate(families):
            split = "train" if index < 3 else ("validation" if index == 3 else "test")
            for n in rng.sample(range(10000), samples_per_family):
                event = RoutingInput(text=template.format(n=n), **metadata)
                splits[split].append({"family": family, "label": label, "input": asdict(event)})
    for records in splits.values():
        rng.shuffle(records)
    return splits


def encode(event):
    """Identical observable metadata for learned and deterministic policies."""
    if isinstance(event, RoutingInput):
        event = asdict(event)
    return (f"command={event['command']} minutes={event['minutes']} "
            f"non_urgent={event['non_urgent']} priority={event['priority']} | {event['text']}")
